argv:
$ErrorActionPreference='Stop';
$data='E:\WebAIBridge\app\data';
$names=@(
  'projects-live-control-plane-cutover-r42.json',
  'projects-live-control-plane-cutover-r42-reconcile.json',
  'projects-live-control-plane-r41.json',
  'projects-operation-ledger-r41.json',
  'supervisor-watchdog.json',
  'state.json'
);
$out=@();
foreach($n in $names){
  $p=Join-Path $data $n;
  if(Test-Path -LiteralPath $p){
    $txt=[IO.File]::ReadAllText($p);
    $out += [pscustomobject]@{
      name=$n;exists=$true;lastWrite=(Get-Item $p).LastWriteTimeUtc.ToString('o');
      sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant();
      text=$txt.Substring(0,[Math]::Min(12000,$txt.Length))
    }
  } else {$out += [pscustomobject]@{name=$n;exists=$false}}
}
$backs=@();
$root=Join-Path $data 'backups';
if(Test-Path $root){
  $backs=@(Get-ChildItem $root -Directory -Filter 'r42-cutover-*' |
    Sort-Object LastWriteTimeUtc -Descending |
    Select-Object -First 5 Name,FullName,@{n='LastWriteUtc';e={$_.LastWriteTimeUtc.ToString('o')}})
}
[pscustomobject]@{files=$out;backups=$backs}|ConvertTo-Json -Depth 7 -Compress
